const SCAN_BUNDLE_WINDOW_SIZE = 64 * 1024;

async function scanBundle(input, deliver) {
  let delivered = 0;
  let lineNumber = 1;
  let fragments = [];
  const decoder = new TextDecoder("utf-8");

  async function processLine(text) {
    if (/^\s*$/.test(text)) {
      return true;
    }

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error(`Invalid JSON on line ${lineNumber}`);
      error.code = "BAD_LINE";
      error.line = lineNumber;
      throw error;
    }

    const result = await deliver(value, lineNumber);
    delivered += 1;
    return result !== false;
  }

  async function processText(text) {
    let start = 0;

    for (let index = 0; index < text.length; index += 1) {
      if (text.charCodeAt(index) !== 10) {
        continue;
      }

      let line;
      if (fragments.length === 0) {
        line = text.slice(start, index);
      } else {
        if (index > start) {
          fragments.push(text.slice(start, index));
        }
        line = fragments.join("");
        fragments = [];
      }

      if (!(await processLine(line))) {
        return false;
      }

      lineNumber += 1;
      start = index + 1;
    }

    if (start < text.length) {
      fragments.push(text.slice(start));
    }

    return true;
  }

  try {
    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        if (!(await processText(decoder.decode()))) {
          return delivered;
        }

        if (fragments.length !== 0) {
          const finalLine = fragments.join("");
          fragments = [];
          await processLine(finalLine);
        }

        return delivered;
      }

      for (
        let offset = 0;
        offset < chunk.byteLength;
        offset += SCAN_BUNDLE_WINDOW_SIZE
      ) {
        const end = Math.min(
          offset + SCAN_BUNDLE_WINDOW_SIZE,
          chunk.byteLength
        );
        const text = decoder.decode(chunk.subarray(offset, end), {
          stream: true
        });

        if (!(await processText(text))) {
          return delivered;
        }
      }
    }
  } finally {
    await input.close();
  }
}
